## 4. Trade Execution Subsystem

```csharp
public class TradeExecutionSubsystem
{
    private readonly IOrderRouter _orderRouter;
    private readonly TradeCostModel _costModel;
    private readonly PortfolioConstraints _constraints;

    public TradeExecutionSubsystem(
        IOrderRouter orderRouter,
        TradeCostModel costModel,
        PortfolioConstraints constraints)
    {
        _orderRouter = orderRouter ?? throw new ArgumentNullException(nameof(orderRouter));
        _costModel = costModel ?? throw new ArgumentNullException(nameof(costModel));
        _constraints = constraints ?? throw new ArgumentNullException(nameof(constraints));
    }

    public List<Trade> GenerateTrades(Portfolio currentPortfolio, Dictionary<string, decimal> targetWeights)
    {
        var trades = new List<Trade>();

        // Calculate current and target positions
        var currentPositions = currentPortfolio.GetPositions();
        var targetPositions = CalculateTargetPositions(currentPortfolio, targetWeights);

        // Generate trades to reach target positions
        foreach (var assetId in currentPositions.Keys)
        {
            var currentQty = currentPositions[assetId];
            var targetQty = targetPositions[assetId];

            if (currentQty > targetQty)
            {
                // Sell position
                var quantity = currentQty - targetQty;
                trades.Add(new Trade
                {
                    AssetId = assetId,
                    Quantity = quantity,
                    Side = TradeSide.Sell,
                    Price = currentPortfolio.GetCurrentPrice(assetId)
                });
            }
            else if (currentQty < targetQty)
            {
                // Buy position
                var quantity = targetQty - currentQty;
                trades.Add(new Trade
                {
                    AssetId = assetId,
                    Quantity = quantity,
                    Side = TradeSide.Buy,
                    Price = currentPortfolio.GetCurrentPrice(assetId)
                });
            }
        }

        // Apply constraints to trades
        ApplyConstraints(trades);

        return trades;
    }

    private Dictionary<string, decimal> CalculateTargetPositions(Portfolio portfolio, Dictionary<string, decimal> targetWeights)
    {
        var targetPositions = new Dictionary<string, decimal>();

        // Calculate target quantity for each asset based on portfolio value
        var portfolioValue = portfolio.TotalValue;
        foreach (var assetId in targetWeights.Keys)
        {
            targetPositions[assetId] = (portfolioValue * targetWeights[assetId]) /
                                      portfolio.GetCurrentPrice(assetId);
        }

        return targetPositions;
    }

    private void ApplyConstraints(List<Trade> trades)
    {
        // Implement constraint application logic
        // This could include position limits, trade size limits, etc.
    }

    public void ExecuteTrades(List<Trade> trades)
    {
        foreach (var trade in trades)
        {
            try
            {
                // Calculate order cost
                var orderCost = _costModel.CalculateOrderCost(trade);

                // Route the order
                _orderRouter.PlaceOrder(trade);

                // Log the trade
                Console.WriteLine($"Executed trade: {trade.AssetId}, {trade.Side}, {trade.Quantity} shares at {trade.Price}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to execute trade: {ex.Message}");
                // Implement retry logic or error handling
            }
        }
    }
}

