## 5. Supporting Classes

```csharp
// Portfolio Class
public class Portfolio
{
    private readonly Dictionary<string, decimal> _assetPrices = new();
    private readonly Dictionary<string, decimal> _positions = new();
    private decimal _cashBalance = 100000m; // Example initial cash

    public IEnumerable<string> AssetIds => _positions.Keys;
    public decimal TotalValue => _cashBalance + _positions.Sum(p => p.Value * GetCurrentPrice(p.Key));

    public void UpdateAssetPrices(string assetId, decimal price)
    {
        _assetPrices[assetId] = price;
    }

    public decimal GetCurrentPrice(string assetId)
    {
        if (_assetPrices.TryGetValue(assetId, out var price))
        {
            return price;
        }
        throw new KeyNotFoundException($"Asset price not found for {assetId}");
    }

    public Dictionary<string, decimal> GetPositions()
    {
        return new Dictionary<string, decimal>(_positions);
    }

    public Dictionary<string, decimal> GetCurrentWeights()
    {
        var totalValue = TotalValue;
        var weights = new Dictionary<string, decimal>();

        foreach (var assetId in _positions.Keys)
        {
            weights[assetId] = (_positions[assetId] * GetCurrentPrice(assetId)) / totalValue;
        }

        return weights;
    }

    public void ApplyTrades(List<Trade> trades)
    {
        foreach (var trade in trades)
        {
            if (trade.Side == TradeSide.Buy)
            {
                _cashBalance -= trade.Quantity * trade.Price;
                _positions[trade.AssetId] = _positions.GetValueOrDefault(trade.AssetId, 0) + trade.Quantity;
            }
            else if (trade.Side == TradeSide.Sell)
            {
                _cashBalance += trade.Quantity * trade.Price;
                _positions[trade.AssetId] = _positions.GetValueOrDefault(trade.AssetId, 0) - trade.Quantity;
                if (_positions[trade.AssetId] <= 0)
                {
                    _positions.Remove(trade.AssetId);
                }
            }
        }
    }
}

